/**
 * Configuration file management utilities
 */ import fs from 'fs/promises';
import path from 'path';
const GITIGNORE_FILENAME = '.gitignore';
/**
 * Ensure .gitignore exists and optionally add entries
 *
 * @param projectPath - Path to project directory
 * @param entries - Optional entries to add to .gitignore
 */ export async function ensureGitignore(projectPath, entries = []) {
    const gitignorePath = path.join(projectPath, GITIGNORE_FILENAME);
    let existingContent = '';
    try {
        existingContent = await fs.readFile(gitignorePath, 'utf-8');
    } catch (error) {
        if (error.code !== 'ENOENT') {
            throw new Error(`Failed to read ${GITIGNORE_FILENAME}: ${error.message}`);
        }
    }
    // Parse existing entries
    const existingLines = existingContent.split(/\r?\n/).filter((line)=>line.trim());
    const existingSet = new Set(existingLines);
    // Add new entries that don't exist
    const newEntries = entries.filter((entry)=>!existingSet.has(entry));
    if (newEntries.length > 0) {
        const newContent = existingContent ? `${existingContent.trimEnd()}\n\n# Figma CMS\n${newEntries.join('\n')}\n` : `# Figma CMS\n${newEntries.join('\n')}\n`;
        await fs.writeFile(gitignorePath, newContent, 'utf-8');
    }
}
